import{af as i,z as t,J as a,ab as o}from"./chunks/framework.ss42i_gG.js";const p=JSON.parse('{"title":"Readings","description":"","frontmatter":{},"headers":[],"relativePath":"terminology/readings.md","filePath":"terminology/readings.md"}'),l={name:"terminology/readings.md"};function n(s,e,d,r,c,h){return t(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793282371000"},[...e[0]||(e[0]=[o('<h1 id="readings" tabindex="-1">Readings <a class="header-anchor" href="#readings" aria-label="Permalink to &quot;Readings&quot;">​</a></h1><p>Readings, or sensor readings, are sent along site <a href="./points">points</a>, and contain additional information that has been recorded by the device, at a given point in time.</p><ul><li>Identifiers: <ul><li>Reading ID: Unique identifier of the point</li><li>Device ID: Device that the point relates to</li><li>Transmission ID: Hash that relates to the transmission the data was received in. Can be used to connect multiple points and readings.</li><li>Gateway ID: If set (and visible), the data was received via a device with this ID</li><li>SensorDeviceID</li></ul></li><li>Timestamps: <ul><li>Time the device recorded the point. (Can be 1970 if the device didn&#39;t know the time)</li><li>Time the point was successfully received by the receiving endpoint</li></ul></li><li>Data: <ul><li>Type of data (see <a href="#types">#types</a>)</li><li>Value of data</li><li>Additional meta data</li></ul></li></ul><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>Different interfaces may expose these details in different ways, and you are encouraged to look at the individual interface documentation.</p></div><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><p>Each reading has a <code>type</code> attribute, which indicates what kind of reading it is, and thus the type of data to expect.</p><p>These types can also be used to filter the data.</p><p>These reading types are sent from most devices:</p><ul><li>temp: Temperature</li><li><a href="#bluetooth-ble-seen">ble_seen</a>: Bluetooth device seen</li><li>chg_voltage: Charging voltage</li></ul><p>Some readings will only be sent by devices that have additional sensors built in, such as the <a href="/docs/pr/35/devices/enviro/">Enviro</a>:</p><ul><li>humidity_bme: Humidity from the BME sensor</li><li>pressure_bme: Pressure from the BME sensor</li><li>temp_bme: Temperature from the BME sensor</li></ul><p>Or by devices that plug into power, such as the <a href="/docs/pr/35/devices/vehicle/">Vehicle Tracker</a>:</p><ul><li>ext_voltage: External voltage being supplied to the device</li></ul><p>Many other sensor readings are available, and will continue to be documented here.</p><p>If you need help understanding a reading type that is not listed here, please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact us</a>.</p><ul><li>humidity</li><li>temp_hw</li><li>pressure_hw</li><li>light</li><li>heartrate</li><li>acc_ext</li><li>acc_maxForce</li><li>acc_maxTilt</li><li>geofence_log</li><li>lora_packet</li><li>uart_blob</li><li>ultra</li><li>unknown</li><li>temp_dht</li><li>tds_adc</li><li>tamper_detected</li><li>max_speed</li><li>loragw_seen_hack</li><li>light_detected</li><li>humidity_dht</li><li>chg_data</li><li>cadence</li><li>ble_seen</li><li>battery</li><li>adcraw_90</li><li>adcraw_245</li><li>adcraw_2</li><li>adcraw_10</li><li>adcraw_0</li><li>adc_90</li><li>adc_245</li><li>adc_10</li><li>accel_3d</li></ul><h3 id="bluetooth-ble-seen" tabindex="-1">Bluetooth (ble_seen) <a class="header-anchor" href="#bluetooth-ble-seen" aria-label="Permalink to &quot;Bluetooth (ble_seen)&quot;">​</a></h3><p>Records data associated with a Bluetooth device seen by the device. Including links to the device entry itself, which will in turn link to data gathered from sensors on that device.</p><h4 id="no-sensors-or-name" tabindex="-1">No sensors or name <a class="header-anchor" href="#no-sensors-or-name" aria-label="Permalink to &quot;No sensors or name&quot;">​</a></h4><p>When a Bluetooth device is seen, but it has no name or sensors, the data may look like this:</p><p>Value: <code>-42</code> Meta: <code>{&quot;rssi&quot;:-42,&quot;sensorCount&quot;:0}</code> RSSI: <code>-42</code> Gateway: <code>7890123</code> Device: <code>123456</code></p><h4 id="sensor-with-name" tabindex="-1">Sensor with name <a class="header-anchor" href="#sensor-with-name" aria-label="Permalink to &quot;Sensor with name&quot;">​</a></h4><p>When a Bluetooth device with sensors and a name is seen, the data may look like this:</p><p>Value: <code>{&quot;name&quot;:&quot;P ID 00A3B6&quot;}</code> Meta: <code>{&quot;rssi&quot;:-42,&quot;sensorCount&quot;:1}</code> RSSI: <code>-42</code> Gateway: <code>7890123</code> Device: <code>123456</code></p><h4 id="ibeacon" tabindex="-1">iBeacon <a class="header-anchor" href="#ibeacon" aria-label="Permalink to &quot;iBeacon&quot;">​</a></h4><p>When an iBeacon device is seen, the following data is included in the reading:</p><p>Value: <code>{&quot;major&quot;:44,&quot;minor&quot;:1234,&quot;power&quot;:1}</code> Meta: <code>{&quot;rssi&quot;:-81,&quot;sensorCount&quot;:1,&quot;ibeacon&quot;:true}</code> RSSI: <code>-81</code> Gateway: <code>7890123</code> Device: <code>123456</code></p><p>The device seen relates to a device entry that will include the MAC address of the iBeacon.</p>',28)])])}const m=i(l,[["render",n]]);export{p as __pageData,m as default};
